import math, os, random, re, sys, time, heapq, base64, zlib
from functools import lru_cache
from collections import defaultdict


class Language:
    def __init__(self, pieces, vocabulary):
        short=set('a i am an as at be by do go he if in is it me my no of on or so to up us we ox ex ax oh ah ha hi ok'.split())
        self.words = {w: 1.0/(i+20)**0.82 for i,w in enumerate(vocabulary) if len(w)>2 or w in short}
        for p in pieces:
            for row in p.replace('_',' ').split('|'):
                for m in re.finditer(r'(?<=[^A-Za-z])[A-Za-z]{2,}(?=[^A-Za-z])',row):
                    w=m.group().lower()
                    self.words[w]=max(self.words.get(w,0),0.001)
        self.total=sum(self.words.values())
        self.prefix=defaultdict(float);self.suffix=defaultdict(float)
        self.count=[defaultdict(float) for _ in range(6)]
        self.context=[defaultdict(float) for _ in range(6)]
        for w,mass in self.words.items():
            for j in range(1,len(w)+1):
                self.prefix[w[:j]]+=mass
                self.suffix[w[-j:]]+=mass
            s=' '+w+' '
            weight=mass*10000
            for q in range(1,6):
                cc=self.count[q];ct=self.context[q]
                for j in range(len(s)-q+1):
                    token=s[j:j+q]
                    cc[token]+=weight
                    ct[token[:-1]]+=weight
        for s in (' 00 ',' 0000 ',' 0000s ',' 0st ',' 0nd ',' 0rd ',' 0th '):
            for q in range(1,6):
                for j in range(len(s)-q+1):
                    self.count[q][s[j:j+q]]+=50
                    self.context[q][s[j:j+q-1]]+=50
        self.norm = str.maketrans({chr(i):('0' if chr(i).isdigit() else ' ') for i in range(128) if not chr(i).isalpha()})
        self.common={w:i for i,w in enumerate(_COMMON.split())}
        self.wpairs=[v*0.5-4 for b in zlib.decompress(base64.b85decode(_WORDPAIRS)) for v in (b>>4,b&15)]
        self.validword=lru_cache(maxsize=50000)(self._validword)
        self.validprefix=lru_cache(maxsize=50000)(self._validprefix)
        self.prob=lru_cache(maxsize=80000)(self._prob)
        self.charlog=lru_cache(maxsize=80000)(self._charlog)
        self.token=lru_cache(maxsize=100000)(self._token)
        self.score=lru_cache(maxsize=100000)(self._score)
        self.join=lru_cache(maxsize=100000)(self._join)

    def _prob(self, s):
        if len(s)==1:
            return math.log((self.count[1].get(s,0)+1)/(self.context[1]['']+27))
        low=math.exp(self.prob(s[1:]))
        q=len(s);a=12.0
        return math.log((self.count[q].get(s,0)+a*low)/(self.context[q].get(s[:-1],0)+a))

    def _charlog(self,s):
        return sum(self.prob(s[max(0,k-4):k+1]) for k in range(len(s)))

    def _token(self,w,left,right):
        if not left and not right:
            return self.charlog(w)
        s=(' ' if left else '')+w+(' ' if right else '')
        logc=self.charlog(s)-(self.charlog(' ') if left else 0)
        if left and right:mass=self.words.get(w,0)
        elif left:mass=self.prefix.get(w,0)
        else:mass=self.suffix.get(w,0)
        p=mass/self.total
        return math.log(p+0.03*math.exp(logc)+1e-30)

    def _validword(self,w):
        if w in self.words:return True
        for ending in ('s','es','ed','ing','ly'):
            if w.endswith(ending):
                root=w[:-len(ending)]
                if root in self.words or root+'e' in self.words or (len(root)>2 and root[-1]==root[-2] and root[:-1] in self.words):return True
        for k in range(3,len(w)-2):
            if w[:k] in self.words and w[k:] in self.words and w[:k] not in ('the','and','for','but','with') and w[k:] not in ('the','and','for','but','with'):
                return True
        return False

    def _validprefix(self,w):
        if w in self.prefix or self.validword(w):return True
        for k in range(3,len(w)):
            if w[:k] in self.words and w[k:] in self.prefix and w[:k] not in ('the','and','for','but','with'):
                return True
        return False

    def _score(self,s):
        if not s:return 0.0
        t=s.lower().translate(self.norm)
        val=self.charlog(t)
        matches=list(re.finditer('[A-Za-z]+',s))
        for m in matches:
            if m.start()>0 and m.end()<len(s):
                word=m.group().lower()
                if word in self.words:val+=2.0
                elif len(word)<=10 and not m.group()[0].isupper():val-=3.0
        for a,b in zip(matches,matches[1:]):
            if s[a.end():b.start()].isspace():
                ai=self.common.get(a.group().lower());bi=self.common.get(b.group().lower())
                if ai is not None and bi is not None:
                    val+=1.0*self.wpairs[ai*len(self.common)+bi]
        val-=7*len(re.findall(r' [.,;:!?]|[a-z][A-Z]|[,;:!?][A-Za-z]',s))
        val-=8*len(re.findall(r'  +[^ ]',s))
        val-=10*len(re.findall(r'[A-Za-z]{2,}[0-9]',s))
        for m in re.finditer(r'[0-9]([A-Za-z]{2,})',s):
            if m.group(1).lower() not in ('st','nd','rd','th'):
                val-=10
        return val

    def _join(self,a,b):
        a,b=a[-20:],b[:20]
        if not a.strip() and not b.strip():return 0.0
        return self.score(a+b)-self.score(a)-self.score(b)


def _small_assemble(pieces):
    return _solve(pieces,_VOCAB.split())


def _solve(pieces,vocabulary):
    n=len(pieces)
    if not n:return []
    rows=[p.replace('_',' ').split('|') for p in pieces]
    hs=[len(r) for r in rows];ws=[len(r[0]) for r in rows]
    total_area=sum(h*w for h,w in zip(hs,ws))
    max_width=60 if total_area>=400 else max(max(ws),int(math.sqrt(total_area*4.2)))
    max_height=14 if total_area>=400 else max(max(hs),int(math.ceil(max_width/4)))
    lm=Language(pieces,vocabulary)
    # Candidate translations for arbitrary partial horizontal contacts.
    links=[[] for _ in pieces]
    for i in range(n):
        keep=[]
        for j in range(n):
            if i==j or ws[i]+ws[j]>60:continue
            vals=[[lm.join(a,b) for b in rows[j]] for a in rows[i]]
            for dy in range(1-hs[j],hs[i]):
                lo=max(0,dy);hi=min(hs[i],dy+hs[j])
                if max(hs[i],dy+hs[j])-min(0,dy)>14:continue
                count=hi-lo
                val=sum(vals[y][y-dy] for y in range(lo,hi))
                val-=1.0*count+2.0
                if dy==0 and hs[i]==hs[j]:val+=1.0*count
                keep.append((val,j,dy,ws[i]))
        keep.sort(reverse=True)
        buckets={}
        for val,j,dy,dx in keep:
            bucket=max(0,dy),min(3,min(hs[i],dy+hs[j])-max(0,dy))
            if buckets.get(bucket,0)>=8:continue
            buckets[bucket]=buckets.get(bucket,0)+1
            links[i].append((j,dy,dx,val))
            links[j].append((i,-dy,-dx,val))
    # A state is a complete page hypothesis, not a piece-to-page decision.
    # Relative positions are normalized; NUL denotes unknown, not whitespace.
    def render(pos):
        y0=min(y for y,x in pos.values());x0=min(x for y,x in pos.values())
        pos={i:(y-y0,x-x0) for i,(y,x) in pos.items()}
        h=max(y+hs[i] for i,(y,x) in pos.items());w=max(x+ws[i] for i,(y,x) in pos.items())
        text=[['\0']*w for _ in range(h)];masks=[0]*h
        for i,(y,x) in pos.items():
            mask=((1<<ws[i])-1)<<x
            for r,row in enumerate(rows[i]):
                masks[y+r]|=mask;text[y+r][x:x+ws[i]]=row
        return pos,masks,[''.join(r) for r in text],w,h

    def edgepotential(text,w,h):
        val=0.0
        for yy,line in enumerate(text):
            if line.startswith('\0'):
                val-=2.0
                continue
            run=line.split('\0',1)[0].lstrip()
            m=re.match('[A-Za-z]+',run)
            if m:
                word=m.group().lower()
                if m.end()<len(run):
                    if lm.validword(word):val+=1.0
                    elif yy and text[yy-1].rstrip().endswith('-'):pass
                    else:val-=6.0
                elif word not in lm.prefix:
                    val-=1.0
            elif run and run[0] in ',;:':val-=3.0
        for yy in range(h-1):
            end=text[yy].rsplit('\0',1)[-1].rstrip()
            start=text[yy+1].split('\0',1)[0].lstrip()
            a=re.search('[A-Za-z]+-$',end)
            b=re.match('[A-Za-z]+',start)
            if a and b:
                joined=a.group()[:-1].lower()+b.group().lower()
                val+=5.0 if lm.validword(joined) else -5.0
            elif end and b:
                a=re.search('[A-Za-z]+[^A-Za-z]*$',end)
                if a:
                    ai=lm.common.get(re.match('[A-Za-z]+',a.group()).group().lower());bi=lm.common.get(b.group().lower())
                    if ai is not None and bi is not None:val+=1.2*lm.wpairs[ai*len(lm.common)+bi]
                if text[yy].endswith('  '):
                    pad=len(text[yy])-len(text[yy].rstrip())
                    if pad>=len(b.group())+1:val-=3.0
        val-=0.10*max(0,w-8*h)
        return val

    def attach(state,j,y,x):
        value,pos,masks,text,w,h,area=state
        wi,hi=ws[j],hs[j]
        nw=max(w,x+wi)-min(0,x);nh=max(h,y+hi)-min(0,y)
        if nw>max_width or nh>max_height or (anchored and (x<0 or y<0)):return None
        shift=max(0,-x);bits=((1<<wi)-1)<<(x+shift)
        delta=0.0;contact=0
        for k,row in enumerate(rows[j]):
            yy=y+k
            if not 0<=yy<h:continue
            if masks[yy]<<shift & bits:return None
            line=text[yy]
            left=line[:x].rsplit('\0',1)[-1] if 0<x<=w else ''
            right=line[x+wi:].split('\0',1)[0] if 0<=x+wi<w else ''
            if left or right:
                combined=left+row+right
                bad=r' [.,;:!?]|[a-z][A-Z]|[,;:!?][A-Za-z]'
                if len(re.findall(bad,combined))>sum(len(re.findall(bad,s)) for s in (left,row,right)):
                    return None
                cuts=(len(left),len(left)+len(row))
                for m in re.finditer('[A-Za-z]+',combined):
                    if any(m.start()<cut<m.end() for cut in cuts) and len(m.group())>=3 and m.group()[0].islower():
                        word=m.group().lower()
                        if m.start()>0:
                            if m.end()<len(combined):
                                if not lm.validword(word):return None
                            elif not lm.validprefix(word):return None
                        elif m.end()<len(combined) and word not in lm.suffix and not lm.validword(word):return None
                    if m.group() in ('The','A','An','This','These','Those','It','He','She','We','They') and m.start()>0:
                        before=combined[:m.start()].rstrip()
                        if before and before[-1] not in '.!?\"\':':
                            return None
                delta+=min(8.0,lm.score(combined)-lm.score(left)-lm.score(row)-lm.score(right))
                contact+=bool(left)+bool(right)
        if not contact:return None
        holes=(nw*nh-area-wi*hi)-(w*h-area)
        gain=delta+0.6*contact-0.60*holes+0.025*sum(c!=' ' for row in rows[j] for c in row)
        newpos=dict(pos);newpos[j]=y,x
        np,nm,nt,nw,nh=render(newpos)
        for line in nt:
            for m in re.finditer(r' {2,}',line):
                if any(c not in ' \0' for c in line[:m.start()]) and any(c not in ' \0' for c in line[m.end():]):
                    return None
        gain+=edgepotential(nt,nw,nh)-edgepotential(text,w,h)
        return value+gain,np,nm,nt,nw,nh,area+wi*hi

    anchor_scores=[]
    for i,rs in enumerate(rows):
        good,bad=0,0
        for row in rs:
            m=re.match('[A-Za-z]+',row)
            if m and ((m.end()<len(row) and lm.validword(m.group().lower())) or (m.end()==len(row) and m.group().lower() in lm.prefix)):
                good+=1
            else:bad+=1
        anchor_scores.append((hs[i]>=2 and rows[i][0][0].isupper() and good>=hs[i]-1,good-bad))
    available=set(range(n));pages=[]
    # Compact, high-support hypotheses are expanded with retained alternatives.
    beamwidth=40 if n<60 else (10 if n<150 else 5)
    while available:
        def seedquality(i):
            best=-1e100
            for j,dy,dx,val in links[i]:
                if j not in available:continue
                count=min(hs[i],dy+hs[j])-max(0,dy)
                best=max(best,val+2.0*max(0,count-1))
            return best+0.01*hs[i]*ws[i]+(10.0 if anchor_scores[i][0] else 0.0)
        seed=max(available,key=seedquality)
        anchored=anchor_scores[seed][0]
        pos,masks,text,w,h=render({seed:(0,0)})
        first=(0.0,pos,masks,text,w,h,ws[seed]*hs[seed])
        beam=[first];best=first;last_best=0.0;stale=0
        for step in range(min(len(available)-1,90)):
            nextstates=[]
            fingerprints=set()
            for state in beam:
                poses={}
                for i,(y,x) in state[1].items():
                    for j,dy,dx,confidence in links[i]:
                        if j not in available or j in state[1]:continue
                        key=j,y+dy,x+dx
                        if confidence>poses.get(key,-1e100):poses[key]=confidence
                # Beam candidates include multi-contact hole insertions even
                # when no single pruned edge had been a strong match.
                if step and step%3==0 and n<250:
                    _,pos,masks,text,w,h,_=state
                    for j in available-pos.keys():
                        if ws[j]*hs[j]>40:continue
                        for y in range(h-hs[j]+1):
                            for x in range(w-ws[j]+1):
                                mask=((1<<ws[j])-1)<<x
                                if not any(mask&masks[r] for r in range(y,y+hs[j])):
                                    poses.setdefault((j,y,x),0.0)
                ranked=sorted(poses,key=poses.get,reverse=True)
                expansions=[]
                for j,y,x in ranked[:180]:
                    new=attach(state,j,y,x)
                    if new is not None:expansions.append(new)
                expansions.sort(key=lambda st:st[0],reverse=True)
                for new in expansions[:beamwidth]:
                    fp=tuple(sorted(new[1].items()))
                    if fp not in fingerprints:
                        fingerprints.add(fp);nextstates.append(new)
            if not nextstates:break
            nextstates.sort(key=lambda st:st[0],reverse=True)
            beam=nextstates[:beamwidth]
            if beam[0][0]>best[0]:best=beam[0]
            if best[0]<=last_best+0.1:stale+=1
            else:stale=0;last_best=best[0]
            if stale>=3:break
        pages.append(best)
        available.difference_update(best[1])
    out=[]
    for p,state in enumerate(pages):
        out.extend([i,p,y,x] for i,(y,x) in state[1].items())
    return out


