import base64
import zlib
import heapq
import time
from functools import lru_cache


def _language(pieces):
    packed = zlib.decompress(base64.b85decode(_CHARS))
    table = [v * 0.5 for b in packed for v in (b >> 4, b & 15)]
    uni, bi, tri = table[:27], table[27:756], table[756:20439]
    words = zlib.decompress(base64.b85decode(_WORDS)).decode().split()
    lex = {w: 1.0 + 0.2 * math.log(1 + 3000 / (r + 10)) for r, w in enumerate(words)}
    for piece in pieces:
        for row in piece.lower().replace('_', ' ').split('|'):
            for m in re.finditer(r"(?<=[^a-z])[a-z]{2,}(?=[^a-z])", row):
                lex[m.group()] = max(1.5, lex.get(m.group(), 0))
    prefixes, suffixes = set(), set()
    for w in lex:
        for k in range(1, len(w)):
            prefixes.add(w[:k])
            suffixes.add(w[k:])

    c4, ctx = {}, {}
    for rank, w in enumerate(lex):
        weight = 20000.0 / (rank + 15)
        s = ' ' + w + ' '
        for i in range(len(s) - 3):
            key = s[i:i+4]
            c4[key] = c4.get(key, 0.0) + weight
            ctx[key[:3]] = ctx.get(key[:3], 0.0) + weight

    @lru_cache(maxsize=30000)
    def fourth(s):
        h = s[:3]
        ix = ((ord(s[-3])-97 if s[-3] != ' ' else 26) * 27 + (ord(s[-2])-97 if s[-2] != ' ' else 26)) * 27 + (ord(s[-1])-97 if s[-1] != ' ' else 26)
        back = tri[ix]
        p = math.exp(-back)
        return -math.log(0.4 * p + 0.6 * (c4.get(s, 0) + 20 * p) / (ctx.get(h, 0) + 20))

    def code(c):
        q = ord(c.lower()) - 97
        return q if 0 <= q < 26 else 26

    @lru_cache(maxsize=120000)
    def seam(a, b):
        a, b = a[-16:], b[:16]
        if not a or not b:
            return 0.0
        if not a.strip() and not b.strip():
            return 0.0
        if len(a) >= 2 and a.endswith('  ') and b.strip():
            return -9.0
        x, y = code(a[-1]), code(b[0])
        if x == y == 26:
            score = -0.5
        else:
            ac = ''.join(c.lower() if 'a' <= c.lower() <= 'z' else ' ' for c in a[-3:])
            bc = ''.join(c.lower() if 'a' <= c.lower() <= 'z' else ' ' for c in b[:3])
            q = fourth(ac + bc[0]) if len(ac) == 3 else (tri[(code(a[-2]) * 27 + x) * 27 + y] if len(a) > 1 else bi[x * 27 + y])
            score = uni[y] - q
            if len(b) > 1:
                z = code(b[1])
                q = fourth(ac[-2:] + bc[:2]) if len(ac) >= 2 else tri[(x * 27 + y) * 27 + z]
                score += bi[y * 27 + z] - q
            if len(b) > 2:
                z = code(b[1]); t = code(b[2])
                score += tri[(y * 27 + z) * 27 + t] - fourth(ac[-1] + bc)
        if a[-1].islower() and b[0].isupper():
            score -= 7.0
        if a[-1].isalpha() and b[0].isalpha():
            ma = re.search('[a-zA-Z]+$', a)
            mb = re.match('[a-zA-Z]+', b)
            word = (ma.group() + mb.group()).lower()
            left, right = ma.start() > 0, mb.end() < len(b)
            if word in lex:
                score += 3.0 + lex[word]
            elif left and right:
                root = word[:-1] if word.endswith('s') else word
                score += 1.0 if root in lex else (-1.0 if len(word) >= 9 else -3.5)
            elif left:
                score += 1.2 if word in prefixes else -1.6
            elif right:
                score += 1.2 if word in suffixes else -1.6
            else:
                score += 0.2
        elif a[-1].isalpha() and b[0] == ' ':
            m = re.search('[a-zA-Z]+$', a)
            w = m.group().lower()
            if w in lex:
                score += 1.0
            elif m.start() > 0:
                score -= 2.5
        if b[0] in '.,;:!?)]' and a[-1] == ' ':
            score -= 7
        if a[-1] in ',;:!?' and b[0].isalpha():
            score -= 6
        return score
    @lru_cache(maxsize=60000)
    def textscore(s):
        if not s:
            return 0.0
        t = ''.join(c.lower() if 'a' <= c.lower() <= 'z' else ' ' for c in s)
        ids = [26 if c == ' ' else ord(c) - 97 for c in t]
        score = 0.0
        for k in range(1, len(t)):
            if k == 1:
                pred = bi[ids[k-1] * 27 + ids[k]]
            elif k == 2:
                pred = tri[(ids[k-2] * 27 + ids[k-1]) * 27 + ids[k]]
            else:
                pred = fourth(t[k-3:k+1])
            score += uni[ids[k]] - pred
        for m in re.finditer('[a-zA-Z]+', s):
            w = m.group().lower()
            if m.start() > 0 and m.end() < len(s):
                if w in lex:
                    score += 2.0 + lex[w]
                elif len(w) < 9 and not m.group()[0].isupper():
                    score -= 2.0
            elif w in lex:
                score += 0.5
        score -= 6 * len(re.findall(r' [.,;:!?]|[a-z][A-Z]|[,;:!?][a-zA-Z]', s))
        score -= 6 * len(re.findall(r'  +[^ ]', s))
        return score
    seam.textscore = textscore
    return seam


def _seed_assemble(pieces):
    n = len(pieces)
    if not n:
        return []
    rows = [p.replace('_', ' ').split('|') for p in pieces]
    heights = [len(r) for r in rows]
    widths = [len(r[0]) for r in rows]
    seam = _language(pieces)
    hints = [[] for _ in pieces]
    initial = []
    for i, ai in enumerate(rows):
        candidates = []
        for j, bj in enumerate(rows):
            if i == j or widths[i] + widths[j] > 60:
                continue
            pair = [[seam(a, b) for b in bj] for a in ai]
            for dy in range(1 - heights[j], heights[i]):
                lo, end = max(0, dy), min(heights[i], dy + heights[j])
                if max(heights[i], dy + heights[j]) - min(0, dy) > 14:
                    continue
                count = end - lo
                score = sum(pair[r][r - dy] for r in range(lo, end)) - 0.7 * count - 1.8
                score += 4.0 * ((dy == 0) + (heights[i] == dy + heights[j])) + 1.0 * max(0, count - 1)
                if score > -3.0:
                    candidates.append((score, i, j, dy, widths[i]))
        candidates.sort(reverse=True)
        kept = {}
        for e in candidates:
            score, _, j, dy, dx = e
            count = min(heights[i], dy + heights[j]) - max(0, dy)
            bucket = max(0, dy), min(3, count)
            if kept.get(bucket, 0) >= 8:
                continue
            kept[bucket] = kept.get(bucket, 0) + 1
            hints[i].append((j, dy, dx))
            hints[j].append((i, -dy, -dx))
            initial.append(e)
    # Each component stores normalized coordinates, occupied masks and text.
    groups = {i: ({i: (0, 0)}, [(1 << widths[i]) - 1] * heights[i], rows[i], widths[i], heights[i]) for i in range(n)}
    owner = list(range(n))
    serial = n
    heap = []
    queued = set()

    def evaluate(a, b, dy, dx):
        ga, ma, ra, wa, ha = groups[a]
        gb, mb, rb, wb, hb = groups[b]
        if max(wa, dx + wb) - min(0, dx) > 60 or max(ha, dy + hb) - min(0, dy) > 14:
            return None
        sa, sb = max(0, -dx), max(0, dx)
        score, contact = 0.0, 0
        for y in range(max(0, dy), min(ha, dy + hb)):
            am, bm = ma[y] << sa, mb[y - dy] << sb
            if am & bm:
                return None
            bits = (am << 1) & bm
            while bits:
                bit = bits & -bits
                bits -= bit
                x = bit.bit_length() - 1
                left = ra[y][:x - sa].rsplit('\x00', 1)[-1][-16:]
                right = rb[y - dy][x - sb:].split('\x00', 1)[0][:16]
                score += seam(left, right)
                contact += 1
            bits = (bm << 1) & am
            while bits:
                bit = bits & -bits
                bits -= bit
                x = bit.bit_length() - 1
                left = rb[y - dy][:x - sb].rsplit('\x00', 1)[-1][-16:]
                right = ra[y][x - sa:].split('\x00', 1)[0][:16]
                score += seam(left, right)
                contact += 1
        return score - 0.7 * contact - 1.8 + 4.0 * ((dy == 0) + (ha == dy + hb)) + 1.0 * max(0, contact - 1) if contact else None

    def propose(a, b, dy, dx):
        if a > b:
            a, b, dy, dx = b, a, -dy, -dx
        key = a, b, dy, dx
        if key in queued:
            return
        queued.add(key)
        value = evaluate(a, b, dy, dx)
        if value is not None and value > 4.0 * ((dy == 0) + (groups[a][4] == dy + groups[b][4])):
            heapq.heappush(heap, (-value, a, b, dy, dx))

    def combine(a, b, dy, dx):
        nonlocal serial
        ga, ma, ra, wa, ha = groups.pop(a)
        gb, mb, rb, wb, hb = groups.pop(b)
        y0, x0 = min(0, dy), min(0, dx)
        h, w = max(ha, dy + hb) - y0, max(wa, dx + wb) - x0
        cells = [['\x00'] * w for _ in range(h)]
        pos = {}
        for g, offy, offx in ((ga, -y0, -x0), (gb, dy - y0, dx - x0)):
            for i, (y, x) in g.items():
                y, x = y + offy, x + offx
                pos[i] = y, x
                for r, row in enumerate(rows[i]):
                    cells[y + r][x:x + widths[i]] = row
        rendered = [''.join(r) for r in cells]
        masks = [sum(1 << x for x, c in enumerate(r) if c != '\x00') for r in rendered]
        serial += 1
        c = serial
        groups[c] = pos, masks, rendered, w, h
        for i in pos:
            owner[i] = c
        for i, (yi, xi) in pos.items():
            for j, ddy, ddx in hints[i]:
                other = owner[j]
                if other == c:
                    continue
                yj, xj = groups[other][0][j]
                propose(c, other, yi + ddy - yj, xi + ddx - xj)
        return c

    for _, i, j, dy, dx in initial:
        propose(i, j, dy, dx)
    while heap:
        neg, a, b, dy, dx = heapq.heappop(heap)
        if a not in groups or b not in groups:
            continue
        combine(a, b, dy, dx)
    # Hyphen continuations provide strong vertical order when available.
    while True:
        best = None
        for a, (ga, ma, ra, wa, ha) in groups.items():
            if '\x00' in ra[-1] or not ra[-1].rstrip().endswith('-'):
                continue
            for b, (gb, mb, rb, wb, hb) in groups.items():
                if a == b or ha + hb > 14 or not rb[0] or not rb[0][0].islower() or '\x00' in rb[0]:
                    continue
                val = seam(ra[-1].rstrip()[:-1], rb[0]) + 5
                if val > 3 and (best is None or val > best[0]):
                    best = val, a, b, ha, 0
        if best is None:
            break
        _, a, b, dy, dx = best
        combine(a, b, dy, dx)
    # Lay out disconnected, nearly full-width bands. Width equality is useful
    # page evidence; line-end -> next-line-start scores are not column scores.
    words = zlib.decompress(base64.b85decode(_WORDS)).decode().split()
    wordids = {w: i for i, w in enumerate(words)}
    payload = zlib.decompress(base64.b85decode(_BGRAMS))
    bigrams = {}
    for k in range(0, len(payload), 4):
        key = int.from_bytes(payload[k:k + 3], 'big')
        bigrams[key] = (payload[k + 3] - 64) / 16

    def wrapscore(a, b):
        end, start = a.rstrip(), b.lstrip()
        if not end or not start:
            return -1.0
        if end.endswith('-') and start[0].islower():
            return 5.0 + seam(end[:-1], start)
        lm = re.search('[A-Za-z]+[^A-Za-z]*$', end)
        rm = re.match('[A-Za-z]+', start)
        if lm is None or rm is None:
            return -1.0
        l = re.match('[A-Za-z]+', lm.group()).group().lower()
        r = rm.group().lower()
        score = 0.0
        if len(a) - len(end) >= len(r) + 1:
            score -= 4.0
        li, ri = wordids.get(l), wordids.get(r)
        if li is not None and ri is not None:
            score += min(4.0, bigrams.get((li << 12) | ri, -0.8))
        if end[-1] in '.!?':
            score += 0.8 if start[0].isupper() else -2.0
        elif start[0].isupper():
            score -= 0.8
        if l in ('the', 'a', 'an', 'of', 'to', 'from', 'with') and r in ('the', 'a', 'an', 'and', 'or', 'but', 'of', 'to', 'from'):
            score -= 2.0
        return score

    bands = {}
    for c, (g, masks, text, w, h) in groups.items():
        if w >= 35 and all('\x00' not in row for row in text):
            bands.setdefault(w, []).append(c)
    for w, ids in bands.items():
        m = len(ids)
        if m < 2:
            continue
        if m > 12:
            while True:
                best = None
                for a in ids:
                    for b in ids:
                        if a == b or groups[a][4] + groups[b][4] > 14:
                            continue
                        val = wrapscore(groups[a][2][-1], groups[b][2][0])
                        if best is None or val > best[0]:
                            best = val, a, b
                if best is None:
                    break
                _, a, b = best
                h = groups[a][4]
                c = combine(a, b, h, 0)
                ids = [q for q in ids if q not in (a, b)] + [c]
            continue
        hs = [groups[c][4] for c in ids]
        pair = [[wrapscore(groups[a][2][-1], groups[b][2][0]) for b in ids] for a in ids]
        totals = [0] * (1 << m)
        dp = {}
        chains = {}
        for mask in range(1, 1 << m):
            bit = mask & -mask
            totals[mask] = totals[mask ^ bit] + hs[bit.bit_length() - 1]
            if totals[mask] > 14:
                continue
            best = None
            for j in range(m):
                if not mask & (1 << j):
                    continue
                previous = mask ^ (1 << j)
                if not previous:
                    entry = 0.0, (j,)
                else:
                    possibilities = [(dp[previous, k][0] + pair[k][j], dp[previous, k][1] + (j,)) for k in range(m) if (previous, k) in dp]
                    if not possibilities:
                        continue
                    entry = max(possibilities)
                dp[mask, j] = entry
                if best is None or entry[0] > best[0]:
                    best = entry
            if best is not None:
                chains[mask] = best[0] - 4.0 - 1.2 * max(0, 10 - totals[mask]), best[1]
        @lru_cache(maxsize=None)
        def partition(mask):
            if not mask:
                return 0.0, ()
            bit = mask & -mask
            best = (-1e100, ())
            sub = mask
            while sub:
                if sub & bit and sub in chains:
                    other = partition(mask ^ sub)
                    val = chains[sub][0] + other[0]
                    if val > best[0]:
                        best = val, (chains[sub][1],) + other[1]
                sub = (sub - 1) & mask
            return best
        for order in partition((1 << m) - 1)[1]:
            a = ids[order[0]]
            for j in order[1:]:
                a = combine(a, ids[j], groups[a][4], 0)
    out = []
    for page, (g, _, _, _, _) in enumerate(groups.values()):
        out.extend([i, page, y, x] for i, (y, x) in g.items())
    return out


"""Generic page-level reconstruction from seed placements, using stdlib only.

API: optimize(pieces, placements, time_budget=5.0) -> indexed quadruples.
Inputs may be indexed quadruples or ordered [page,y,x] triples. Omitted IDs and
page=-1 are outliers; the search can omit further incompatible seed clusters.
No truth, piece IDs, benchmark text, or supplied page count is used. The module
uses the existing solver's language model (set LANGUAGE_FACTORY to inject one).
LAST_REPORT describes inferred geometry, candidate page counts and search work.
"""
import math
import random
import time
from collections import Counter, defaultdict

LANGUAGE_FACTORY = None
LAST_REPORT = {}
_NULL = '\x00'
_BAD = -1e90


def _model(pieces):
    return LANGUAGE_FACTORY(pieces) if LANGUAGE_FACTORY else _language(pieces)


def _normalize(pieces, placements):
    n = len(pieces)
    indexed = any(len(p) == 4 for p in placements)
    result = {}
    for index, record in enumerate(placements):
        if not all(type(v) is int for v in record):
            raise ValueError('placement values must be integers')
        if indexed:
            if len(record) != 4:
                raise ValueError('mixed placement record formats')
            i, p, y, x = record
        else:
            if len(record) != 3 or len(placements) != n:
                raise ValueError('ordered placements require one triple per piece')
            i, (p, y, x) = index, record
        if i in result or not 0 <= i < n or p < -1:
            raise ValueError('duplicate/invalid piece ID or page')
        result[i] = p, y, x
    return result


class _Layout:
    __slots__ = ('pos', 'rows', 'masks', 'width', 'height', 'area', 'scores', 'lang', 'value')

    def __init__(self, pos, source, scorer):
        if not pos:
            self.pos, self.rows, self.masks = {}, [], []
            self.width = self.height = self.area = 0
            self.scores, self.lang, self.value = [], 0.0, 0.0
            return
        top = min(y for y, x in pos.values())
        left = min(x for y, x in pos.values())
        self.pos = {i: (y-top, x-left) for i, (y, x) in pos.items()}
        self.height = max(y+len(source[i]) for i, (y, x) in self.pos.items())
        self.width = max(x+len(source[i][0]) for i, (y, x) in self.pos.items())
        self.area = sum(len(source[i])*len(source[i][0]) for i in pos)
        cells = [[_NULL]*self.width for _ in range(self.height)]
        for i, (y, x) in self.pos.items():
            for dy, row in enumerate(source[i]):
                if any(c != _NULL for c in cells[y+dy][x:x+len(row)]):
                    raise ValueError('overlapping seed rectangles')
                cells[y+dy][x:x+len(row)] = row
        self.rows = [''.join(r) for r in cells]
        self.masks = [sum(1 << x for x, c in enumerate(r) if c != _NULL) for r in self.rows]
        self.scores = [sum(scorer(s) for s in r.split(_NULL) if s) for r in self.rows]
        self.lang = sum(self.scores)
        # Unknown cells remain unknown, not spaces. Reward filled interior holes,
        # but keep this weak relative to a completed English word.
        internal = sum(max(0, m.bit_length()-(m & -m).bit_length()+1-m.bit_count()) if m else 0 for m in self.masks)
        contacts = sum(1 for i,(y,x) in self.pos.items() if x>0 for dy in range(len(source[i])) if cells[y+dy][x-1] != _NULL)
        intrinsic = sum(scorer(row) for i in self.pos for row in source[i])
        self.value = self.lang - intrinsic - 0.045*(self.width*self.height-self.area) - 0.09*internal - 0.35*contacts


def _geometry(source, layouts):
    area = sum(len(r)*len(r[0]) for r in source)
    mw, mh = max(len(r[0]) for r in source), max(len(r) for r in source)
    if area >= 400 or mw >= 35 or mh >= 9:
        lower = max(1, math.ceil(area*0.90/840))
        upper = max(lower, math.ceil(area/400))
        counts = list(range(lower, min(upper, 8)+1))
        target = max(lower, min(upper, int(area/600+0.5)))
        # The challenge's broad dimension prior; actual sizes selected from seed
        # width modes and total occupied area, not the number of seed clusters.
        widths = Counter()
        for g in layouts:
            if g.width >= 35 and g.area/(g.width*g.height) >= 0.75:
                widths[g.width] += g.area
        w0 = max(widths, key=widths.get) if widths else max(40, min(60, round(math.sqrt(area/max(1,target)*4.2))))
        h0 = max(10, min(14, math.ceil(area/max(1,target)/max(40,w0))))
        candidates = [(target, max(mw,w0), max(mh,h0))]
        for count in sorted(counts, key=lambda k: abs(k-target)):
            for w, h in ((60,14), (max(40,w0),14), (max(40,w0),max(10,h0))):
                if w >= mw and h >= mh and count*w*h >= 0.90*area:
                    candidates.append((count,w,h))
        return area, counts, list(dict.fromkeys(candidates)), 'large-400..840-area'
    # Small documents use dimensions derived from actual rectangle scale. This
    # deliberately does not inherit a badly sprawling seed's bounding box.
    w0 = max(mw, round(3.6*mw))
    h0 = max(mh, mh+2)
    target = max(1, min(8, int(area/max(1,w0*h0)+0.5)))
    counts = list(range(max(1,target-1), min(8,target+1)+1))
    candidates = [(target,w0,h0), (target,max(mw,w0+3),h0+1), (target,max(mw,w0-2),h0+1)]
    for count in counts:
        w = max(mw, round(math.sqrt(area/count*5.0)))
        h = max(mh, math.ceil(area/count/w))
        if count*w*h >= area*0.90:
            candidates.append((count,w,h))
    return area, counts, list(dict.fromkeys(candidates)), 'small-piece-scale'


def _split(layout, source, seam, scorer, maxw, maxh):
    """Split weak seed bridges; further cut any rigid seed that cannot fit.

    A maximum-spanning forest keeps strongly supported multirow translations.
    Recursive weakest-tree cuts restore legal geometry without pixel cropping.
    """
    ids = list(layout.pos)
    edges = []
    for k, i in enumerate(ids):
        yi, xi = layout.pos[i]
        hi, wi = len(source[i]), len(source[i][0])
        for j in ids[k+1:]:
            yj, xj = layout.pos[j]
            hj, wj = len(source[j]), len(source[j][0])
            weight, support = 0.0, 0
            if xi+wi == xj or xj+wj == xi:
                for y in range(max(yi,yj), min(yi+hi,yj+hj)):
                    if xi < xj:
                        a,b = source[i][y-yi],source[j][y-yj]
                    else:
                        a,b = source[j][y-yj],source[i][y-yi]
                    weight += seam(a,b)-0.7
                    support += 1
            elif yi+hi == yj or yj+hj == yi:
                overlap = min(xi+wi,xj+wj)-max(xi,xj)
                if overlap > 0:
                    weight, support = -2.0+0.01*overlap, 1
            if support and weight >= 3.0+1.5*(support==1):
                edges.append((weight,i,j))
    parent = {i:i for i in ids}
    def root(i):
        while i != parent[i]:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i
    tree=[]
    for weight,i,j in sorted(edges,reverse=True):
        a,b=root(i),root(j)
        if a!=b:
            parent[a]=b
            tree.append((weight,i,j))
    def parts(edges):
        adj={i:[] for i in ids}
        for weight,i,j in edges:
            adj[i].append(j); adj[j].append(i)
        seen=set(); groups=[]
        for i in ids:
            if i in seen: continue
            pending=[i]; part=[]; seen.add(i)
            while pending:
                q=pending.pop();part.append(q)
                for j in adj[q]:
                    if j not in seen: seen.add(j);pending.append(j)
            groups.append(_Layout({j:layout.pos[j] for j in part},source,scorer))
        return groups
    groups=parts(tree)
    while any(g.width>maxw or g.height>maxh for g in groups) and tree:
        bad=set(i for g in groups if g.width>maxw or g.height>maxh for i in g.pos)
        removable=[e for e in tree if e[1] in bad and e[2] in bad]
        if not removable: break
        tree.remove(min(removable))
        groups=parts(tree)
    return groups


class _Search:
    def __init__(self, source, seam, end, rng):
        self.source,self.seam,self.scorer=source,seam,seam.textscore
        self.end,self.rng=end,rng
        self.evaluations=0
        self.empty=_Layout({},source,self.scorer)


    def layout(self,pos):
        return _Layout(pos,self.source,self.scorer)

    def merged(self,a,b,y,x):
        pos=dict(a.pos)
        pos.update({i:(yy+y,xx+x) for i,(yy,xx) in b.pos.items()})
        return self.layout(pos)

    def proposals(self,a,b,W,H,limit=5,explore=False):
        """Enumerate exact integer cluster transforms, including interior holes.

        Rectangular whitespace is occupied. A cheap whole-contact seam screen
        precedes full-context scoring of the best candidates on BOTH sides.
        """
        if not a.pos:
            if b.width <= W and b.height <= H:
                return [(b.value,0,0,b)]
            return []
        if b.width>W or b.height>H:
            return []
        candidates=[]
        ax,ay=a.width,a.height
        for y in range(max(-b.height,ay-H),min(ay,H-b.height)+1):
            low,high=max(0,y),min(ay,y+b.height)
            for x in range(max(-b.width,ax-W),min(ax,W-b.width)+1):
                # Offset may be negative: shift both row masks into >=0 bits.
                sa,sb=max(0,-x),max(0,x)
                collision=False; contact=0; score=0.0
                for yy in range(low,high):
                    am,bm=a.masks[yy]<<sa,b.masks[yy-y]<<sb
                    if am & bm:
                        collision=True;break
                    bits=(am<<1)&bm
                    while bits:
                        bit=bits & -bits;bits-=bit
                        xx=bit.bit_length()-1
                        left=a.rows[yy][:xx-sa].rsplit(_NULL,1)[-1][-16:]
                        right=b.rows[yy-y][xx-sb:].split(_NULL,1)[0][:16]
                        score+=self.seam(left,right)-0.6;contact+=1
                    bits=(bm<<1)&am
                    while bits:
                        bit=bits & -bits;bits-=bit
                        xx=bit.bit_length()-1
                        left=b.rows[yy-y][:xx-sb].rsplit(_NULL,1)[-1][-16:]
                        right=a.rows[yy][xx-sa:].split(_NULL,1)[0][:16]
                        score+=self.seam(left,right)-0.6;contact+=1
                if collision: continue
                nw=max(ax,x+b.width)-min(0,x)
                nh=max(ay,y+b.height)-min(0,y)
                extra=nw*nh-ax*ay-b.area
                # Compactness is intentionally much weaker than language. A
                # no-contact transform remains eligible for vertical packing.
                rough=score-0.06*extra
                if not contact:
                    rough-=0.25
                # Aligned outer boundaries are weak layout evidence, not LM.
                rough+=0.22*((x==0)+(x+b.width==ax))
                candidates.append((rough,contact,y,x))
        if not candidates:return []
        candidates.sort(reverse=True)
        # Retain distinct transforms and disconnected placements; otherwise all
        # top seam scores can be copies of one misleading attachment.
        chosen=candidates[:max(12,limit*3)]
        disconnected=[c for c in candidates if c[1]==0]
        chosen.extend(disconnected[:3])
        if explore and len(candidates)>len(chosen):
            chosen.extend(self.rng.sample(candidates,min(3,len(candidates))))
        exact=[]
        for rough,contact,y,x in chosen:
            self.evaluations+=1
            merged=self.merged(a,b,y,x)
            delta=merged.value-a.value-b.value
            # A complete text run is evaluated only once, even when a fragment
            # bridges two other fragments. No historical seam accumulation.
            exact.append((delta,y,x,merged))
        exact.sort(key=lambda t:t[0],reverse=True)
        unique=[];seen=set()
        for item in exact:
            key=item[1:3]
            if key not in seen:
                seen.add(key);unique.append(item)
            if len(unique)>=limit:break
        return unique

    def pack(self,groups,K,W,H,beam_width=4):
        order=sorted(range(len(groups)),key=lambda i:(groups[i].area,groups[i].width*groups[i].height),reverse=True)
        # State value excludes each group's constant internal language score.
        beam=[(0.0,[self.empty]*K,{})]
        # Distinct large islands are provisional page anchors. Packing two of
        # them into one empty page merely because vertical whitespace is free
        # destroys one-to-one page assignment without any supporting English.
        anchor_count=min(K,len(order))
        self.anchors=set(order[:anchor_count])
        processed=0
        for ordinal,gi in enumerate(order):
            if time.perf_counter()>self.end:break
            g=groups[gi]; states=[]
            for value,pages,assignment in beam:
                empty_done=False
                for p,a in enumerate(pages):
                    if ordinal<anchor_count and p!=ordinal:continue
                    if not a.pos:
                        if empty_done:continue
                        empty_done=True
                    for delta,y,x,new in self.proposals(a,g,W,H,limit=3):
                        np=pages[:];np[p]=new
                        na=dict(assignment);na[gi]=p
                        # A small page-opening cost prefers sharing genuine
                        # capacity but never overwhelms incompatible language.
                        change=(new.value-a.value-g.value) if not a.pos else delta
                        states.append((value+change-(2.0 if not a.pos else 0),np,na))
                # Explicit null hypothesis: incompatible clusters need not fit.
                na=dict(assignment);na[gi]=-1
                states.append((value-0.9*g.area-4.0-g.value,pages,na))
            states.sort(key=lambda s:s[0],reverse=True)
            beam=states[:beam_width]
            processed+=1
        best=max(beam,key=lambda s:s[0])
        return best,processed

    def refine(self,state,groups,K,W,H,rounds=2):
        value,pages,assignment=state
        # Assignment is cluster-level; origins are recovered from each page's
        # normalized piece coordinates, so normalization never loses offsets.
        best=(value,pages[:],dict(assignment))
        ids=list(assignment)
        for epoch in range(rounds):
            self.rng.shuffle(ids)
            changed=False
            for gi in ids:
                if gi in self.anchors:continue
                if time.perf_counter()>self.end:return best
                p=assignment[gi];g=groups[gi]
                if p>=0:
                    old=pages[p]
                    remove=self.layout({i:xy for i,xy in old.pos.items() if i not in g.pos})
                    removal=remove.value-old.value+g.value
                else:
                    old=self.empty;remove=self.empty
                    removal=0.9*g.area+4.0+g.value
                # Full cluster moves (not individual-edge moves) can relocate a
                # disconnected band between pages and slide it into an old hole.
                choices=[]
                for q,a in enumerate(pages):
                    target=remove if q==p else a
                    for delta,y,x,new in self.proposals(target,g,W,H,limit=2,explore=epoch>0):
                        gain=removal+new.value-target.value-g.value
                        if p>=0 and not remove.pos:gain+=2.0
                        if not target.pos:gain-=2.0
                        choices.append((gain,q,new))
                if p>=0:
                    choices.append((removal-0.9*g.area-4.0-g.value,-1,self.empty))
                if not choices:continue
                gain,q,new=max(choices,key=lambda t:t[0])
                if gain<=0.15:continue
                if p>=0:
                    pages=pages[:];pages[p]=remove
                else:pages=pages[:]
                if q>=0:pages[q]=new
                assignment=dict(assignment);assignment[gi]=q
                value+=gain;changed=True
                if value>best[0]:best=(value,pages[:],dict(assignment))
            if not changed:break
        return best


def optimize(pieces, placements, time_budget=5.0):
    """Merge, relocate and pack seed clusters into inferred page geometries.

    The budget is a soft wall-clock bound, checked at cluster/move boundaries.
    On incomplete search, unprocessed clusters retain independent safe pages;
    they are not silently discarded. Explicitly rejected clusters are omitted.
    """
    global LAST_REPORT
    start=time.perf_counter()
    original=[list(p) for p in placements]
    if not pieces or time_budget<=0:
        LAST_REPORT={'elapsed':time.perf_counter()-start,'status':'unchanged'}
        return original
    source=[p.replace('_',' ').split('|') if isinstance(p,str) else list(p) for p in pieces]
    if any(not r or not r[0] or any(len(x)!=len(r[0]) for x in r) for r in source):
        raise ValueError('pieces must be nonempty rectangles')
    normalized=_normalize(pieces,placements)
    seed=defaultdict(dict)
    for i,(p,y,x) in normalized.items():
        if p>=0:seed[p][i]=(y,x)
    if not seed:return original
    seam=_model(['|'.join(r).replace(' ','_') for r in source]);scorer=seam.textscore
    layouts=[_Layout(pos,source,scorer) for pos in seed.values()]
    area,counts,geometry,regime=_geometry(source,layouts)
    # Compare layouts with the same page-count prior, not raw text likelihood:
    # otherwise a larger canvas gets unearned freedom to invent long rows.
    target=geometry[0][0]
    search=_Search(source,seam,start+max(0.01,time_budget),random.Random(743921))
    reports=[];best=None
    max_candidates=min(1 if len(source)>180 else 4,len(geometry))

    for trial,(K,W,H) in enumerate(geometry[:max_candidates]):
        if time.perf_counter()>start+time_budget:break
        trial_start=time.perf_counter()
        # Reserve time for alternative geometries, but first hypothesis receives
        # twice the effort. Search does not consult external evaluation scores.
        available=start+time_budget-trial_start
        search.end=trial_start+available/(1+0.6*(max_candidates-trial-1))
        groups=[]
        for g in layouts:
            if len(source)>180 and len(g.pos)>=3 and g.width<=W and g.height<=H:
                groups.append(g)
            else:
                groups.extend(_split(g,source,seam,scorer,W,H))
        state,processed=search.pack(groups,K,W,H,beam_width=3 if len(groups)<160 else 2)
        if processed==len(groups):
            state=search.refine(state,groups,K,W,H,rounds=2)
        value,pages,assignment=state
        # Penalize unprocessed clusters exactly like outliers for model
        # comparison, but return them intact if this is the selected partial.
        unprocessed=[i for i in range(len(groups)) if i not in assignment]
        objective=(sum(page.value for page in pages)
                   -sum(0.9*groups[i].area+4 for i,p in assignment.items() if p<0)
                   -sum(0.9*groups[i].area+4 for i in unprocessed)
                   -2.0*sum(bool(page.pos) for page in pages)-30.0*abs(K-target))
        reports.append({'pages':K,'width':W,'height':H,'clusters':len(groups),'processed':processed,
                        'objective':objective,'placed_pieces':sum(len(p.pos) for p in pages),
                        'elapsed':time.perf_counter()-trial_start})
        if best is None or objective>best[0]:best=(objective,pages,groups,assignment,unprocessed,(K,W,H))
    if best is None:
        LAST_REPORT={'elapsed':time.perf_counter()-start,'status':'budget_exhausted_before_search',
                     'area':area,'regime':regime,'candidate_page_counts':counts,'trials':[]}
        return original
    objective,pages,groups,assignment,unprocessed,chosen=best
    output=[];pnum=0
    for page in pages:
        if page.pos:
            output.extend([i,pnum,y,x] for i,(y,x) in page.pos.items());pnum+=1
    for gi in unprocessed:
        output.extend([i,pnum,y,x] for i,(y,x) in groups[gi].pos.items());pnum+=1
    placed={r[0] for r in output}
    output.extend([i,-1,0,0] for i in range(len(pieces)) if i not in placed)
    output.sort()
    LAST_REPORT={'elapsed':time.perf_counter()-start,'area':area,'regime':regime,
                 'candidate_page_counts':counts,'geometry_candidates':[list(g) for g in geometry],
                 'chosen_geometry':list(chosen),'seed_clusters':len(layouts),
                 'output_pages':pnum,'evaluations':search.evaluations,'trials':reports}
    return output



def assemble(pieces):
    if not pieces:
        return []
    area = sum(len(p.split('|')) * len(p.split('|')[0]) for p in pieces)
    small = area < 400 and max(len(p.split('|')[0]) for p in pieces) < 35
    if small:
        result = _small_assemble(pieces)
        counts = Counter(record[1] for record in result)
        if any(count > 1 for count in counts.values()):
            result = [record for record in result if counts[record[1]] > 1]
    else:
        seeds = _seed_assemble(pieces)
        result = optimize(pieces, seeds, time_budget=8.0)
    return [list(record) for record in result if record[1] >= 0]


if __name__ == '__main__':
    fptr = open(os.environ['OUTPUT_PATH'], 'w')

    pieces_count = int(input().strip())

    pieces = []

    for _ in range(pieces_count):
        pieces_item = input()
        pieces.append(pieces_item)

    result = assemble(pieces)

    fptr.write('\n'.join([' '.join(map(str, x)) for x in result]))
    fptr.write('\n')

    fptr.close()
